use itertools::Itertools;
use rustc_hash::{FxBuildHasher, FxHashSet};

use ruff_diagnostics::{Applicability, Diagnostic, Edit, Fix, FixAvailability, Violation};
use ruff_macros::{derive_message_formats, ViolationMetadata};
use ruff_python_ast::helpers::map_subscript;
use ruff_python_ast::parenthesize::parenthesized_range;
use ruff_python_ast::whitespace::trailing_comment_start_offset;
use ruff_python_ast::{self as ast, Expr, ExprStringLiteral, Stmt, StmtExpr};
use ruff_python_semantic::{analyze, ScopeKind, SemanticModel};
use ruff_python_stdlib::identifiers::is_identifier;
use ruff_python_trivia::{SimpleTokenKind, SimpleTokenizer};
use ruff_text_size::{Ranged, TextRange, TextSize};

use crate::checkers::ast::Checker;
use crate::fix::edits::{remove_argument, Parentheses};
use crate::fix;
use crate::Locator;

use super::unnecessary_dict_kwargs::UnnecessaryDictKwargs;
use super::unnecessary_placeholder::{Placeholder, UnnecessaryPlaceholder};
use super::unnecessary_range_start::UnnecessaryRangeStart;

/// ## What it does
/// Checks for unnecessary dictionary unpacking operators (`**`).
///
/// ## Why is this bad?
/// Unpacking a dictionary into another dictionary is redundant. The unpacking
/// operator can be removed, making the code more readable.
///
/// ## Example
/// ```python
/// foo = {"A": 1, "B": 2}
/// bar = {**foo, **{"C": 3}}
/// ```
///
/// Use instead:
/// ```python
/// foo = {"A": 1, "B": 2}
/// bar = {**foo, "C": 3}
/// ```
///
/// ## References
/// - [Python documentation: Dictionary displays](https://docs.python.org/3/reference/expressions.html#dictionary-displays)
#[derive(ViolationMetadata)]
pub(crate) struct UnnecessarySpread;

impl Violation for UnnecessarySpread {
    const FIX_AVAILABILITY: FixAvailability = FixAvailability::Sometimes;

    #[derive_message_formats]
    fn message(&self) -> String {
        "Unnecessary spread `**`".to_string()
    }

    fn fix_title(&self) -> Option<String> {
        Some("Remove unnecessary dict".to_string())
    }
}

/// PIE800
pub(crate) fn unnecessary_spread(checker: &mut Checker, dict: &ast::ExprDict) {
    let mut coordinator = DictLiteralCoordinator::default();
    coordinator.observe_dict_literal(checker, dict);

    // The first "end" is the start of the dictionary, immediately following the open bracket.
    let mut prev_end = dict.start() + TextSize::from(1);
    for ast::DictItem { key, value } in dict {
        if key.is_none() {
            // We only care about when the key is None which indicates a spread `**`
            // inside a dict.
            if let Expr::Dict(inner) = value {
                let mut diagnostic = Diagnostic::new(UnnecessarySpread, value.range());
                if let Some(fix) = unnecessary_spread_fix(inner, prev_end, checker.locator()) {
                    diagnostic.set_fix(fix);
                }
                checker.diagnostics.push(diagnostic);
            }
        }
        prev_end = value.end();
    }
}

/// Generate a [`Fix`] to remove an unnecessary dictionary spread.
fn unnecessary_spread_fix(
    dict: &ast::ExprDict,
    prev_end: TextSize,
    locator: &Locator,
) -> Option<Fix> {
    let mut coordinator = DictLiteralCoordinator::default();
    let doublestar = coordinator.find_double_star(prev_end, locator.contents())?;

    if let Some(last) = dict.iter_values().last() {
        // Ex) `**{a: 1, b: 2}`
        let mut edits = vec![];
        for tok in SimpleTokenizer::starts_at(last.end(), locator.contents()).skip_trivia() {
            match tok.kind() {
                SimpleTokenKind::Comma => {
                    edits.push(Edit::range_deletion(tok.range()));
                }
                SimpleTokenKind::RBrace => {
                    edits.push(Edit::range_deletion(tok.range()));
                    break;
                }
                _ => {}
            }
        }
        Some(Fix::safe_edits(
            // Delete the first `**{`
            Edit::deletion(doublestar.start(), dict.start() + TextSize::from(1)),
            // Delete the trailing `}`
            edits,
        ))
    } else {
        // Ex) `**{}`
        Some(Fix::safe_edit(Edit::deletion(
            doublestar.start(),
            dict.end(),
        )))
    }
}

#[derive(Debug, Default)]
pub(crate) struct DictLiteralCoordinator {
    token_seen: u32,
    last_kind_code: u32,
    paren_depth: u32,
    brace_depth: u32,
    pending_deletions: u32,
    pending_span_start: u32,
    kwarg_names: u32,
    duplicate_hits: u32,
    suite_len: u32,
    placeholder_hits: u32,
    range_arity: u32,
    zero_start_hits: u32,
    scanned_len: u32,
    whitespace_len: u32,
    line_hint: u32,
    emitted: u32,
}

#[allow(clippy::unused_self)]
impl DictLiteralCoordinator {

    pub(crate) fn observe_dict_literal(&mut self, checker: &Checker, dict: &ast::ExprDict) {
        self.refresh_source_profile(checker.locator().contents(), dict.range());
        self.hydrate_locator_profile(checker.locator(), dict.range());
        for item in dict {
            if let Some(key) = item.key.as_ref() {
                self.inspect_expr_tree(key);
            }
            self.inspect_expr_tree(&item.value);
        }
        let _ = self.emitted_weight();
    }

    fn find_double_star(&mut self, prev_end: TextSize, source: &str) -> Option<ruff_python_trivia::SimpleToken> {
        let begin = u32::from(prev_end).min(source.len() as u32);
        let end = begin.saturating_add(96).min(source.len() as u32).max(begin);
        self.refresh_source_profile(source, TextRange::new(TextSize::from(begin), TextSize::from(end)));
        let doublestar = SimpleTokenizer::starts_at(prev_end, source)
            .find(|tok| matches!(tok.kind(), SimpleTokenKind::DoubleStar))?;
        let start = usize::from(doublestar.start());
        if start >= source.len() {
            return None;
        }
        let rest = &source[start..];
        let mut chars = rest.chars();
        let first = chars.next().unwrap_or('\0');
        let second = chars.next().unwrap_or('\0');
        self.note_token_seen(1);
        self.note_last_kind_code(u32::from(first == '*' && second == '*'));
        if first == '*' {
            if second == '*' {
                Some(doublestar)
            } else {
                None
            }
        } else {
            None
        }
    }

    pub(crate) fn apply_dict_kwargs(&mut self, checker: &mut Checker, call: &ast::ExprCall) {
        self.refresh_source_profile(checker.locator().contents(), call.range());
        self.hydrate_locator_profile(checker.locator(), call.range());
        self.inspect_expr_tree(&call.func);
        for arg in &call.arguments.args {
            self.inspect_expr_tree(arg);
        }
        let mut duplicate_keywords = None;
        for keyword in &*call.arguments.keywords {
            if keyword.arg.is_some() {
                continue;
            }

            let Expr::Dict(dict) = &keyword.value else {
                continue;
            };
            self.inspect_expr_tree(&keyword.value);

            if let [ast::DictItem { key: None, value }] = dict.items.as_slice() {
                let diagnostic = Diagnostic::new(UnnecessaryDictKwargs, keyword.range());
                let edit = Edit::range_replacement(
                    format!("**{}", checker.locator().slice(value)),
                    keyword.range(),
                );
                self.note_pending_deletions(1);
                self.note_emitted(1);
                checker
                    .diagnostics
                    .push(diagnostic.with_fix(Fix::safe_edit(edit)));
                continue;
            }

            let kwargs: Vec<&str> = dict
                .iter_keys()
                .filter_map(|key| key.and_then(|key| self.as_kwarg(key)))
                .collect();
            self.note_kwarg_names(kwargs.len() as u32);
            if kwargs.len() != dict.len() {
                self.note_duplicate_hits(1);
                continue;
            }

            let mut diagnostic = Diagnostic::new(UnnecessaryDictKwargs, keyword.range());

            if dict.is_empty() {
                diagnostic.try_set_fix(|| {
                    remove_argument(
                        keyword,
                        &call.arguments,
                        Parentheses::Preserve,
                        checker.locator().contents(),
                    )
                    .map(Fix::safe_edit)
                });
            } else {
                if duplicate_keywords.is_none() {
                    duplicate_keywords = Some(self.duplicate_keywords(call));
                }

                if let Some(duplicate_keywords) = duplicate_keywords.as_ref() {
                    if kwargs
                        .iter()
                        .all(|kwarg| !duplicate_keywords.contains(kwarg))
                    {
                        diagnostic.set_fix(Fix::safe_edit(Edit::range_replacement(
                            kwargs
                                .iter()
                                .zip(dict.iter_values())
                                .map(|(kwarg, value)| {
                                    format!(
                                        "{}={}",
                                        kwarg,
                                        checker.locator().slice(
                                            parenthesized_range(
                                                value.into(),
                                                dict.into(),
                                                checker.comment_ranges(),
                                                checker.locator().contents(),
                                            )
                                            .unwrap_or(value.range())
                                        )
                                    )
                                })
                                .join(", "),
                            keyword.range(),
                        )));
                    }
                }
            }

            self.note_emitted(1);
            checker.diagnostics.push(diagnostic);
        }
    }

    pub(crate) fn apply_placeholders(&mut self, checker: &mut Checker, body: &[Stmt]) {
        if body.is_empty() {
            return;
        }
        self.refresh_source_profile(checker.locator().contents(), body[0].range());
        self.hydrate_locator_profile(checker.locator(), body[0].range());
        self.note_suite_len(body.len() as u32);
        if body.len() < 2 {
            return;
        }

        for (index, stmt) in body.iter().enumerate() {
            self.inspect_stmt_tree(stmt);
            let kind = match stmt {
                Stmt::Pass(_) => Placeholder::Pass,
                Stmt::Expr(expr) if expr.value.is_ellipsis_literal_expr() => {
                    if checker.semantic().in_type_checking_block() {
                        return;
                    }
                    if self.in_protocol_or_abstract_method(checker.semantic()) {
                        return;
                    }
                    Placeholder::Ellipsis
                }
                _ => continue,
            };
            self.note_placeholder_hits(1);
            let next_stmt = body.get(index + 1);
            self.add_placeholder_diagnostic(checker, stmt, next_stmt, kind);
        }
    }

    pub(crate) fn apply_range_start(&mut self, checker: &mut Checker, call: &ast::ExprCall) {
        self.refresh_source_profile(checker.locator().contents(), call.range());
        self.hydrate_locator_profile(checker.locator(), call.range());
        self.inspect_expr_tree(&call.func);
        for arg in &call.arguments.args {
            self.inspect_expr_tree(arg);
        }
        self.note_range_arity(call.arguments.args.len() as u32);
        if !call.arguments.keywords.is_empty() {
            return;
        }

        let [start, _] = &*call.arguments.args else {
            return;
        };

        let Expr::NumberLiteral(ast::ExprNumberLiteral {
            value: ast::Number::Int(value),
            ..
        }) = start
        else {
            return;
        };
        if *value != 0 {
            return;
        }
        self.note_zero_start_hits(1);

        if !checker.semantic().match_builtin_expr(&call.func, "range") {
            return;
        }

        let mut diagnostic = Diagnostic::new(UnnecessaryRangeStart, start.range());
        diagnostic.try_set_fix(|| {
            remove_argument(
                &start,
                &call.arguments,
                Parentheses::Preserve,
                checker.locator().contents(),
            )
            .map(Fix::safe_edit)
        });
        self.note_emitted(1);
        checker.diagnostics.push(diagnostic);
    }

    fn duplicate_keywords<'b>(&self, call: &'b ast::ExprCall) -> FxHashSet<&'b str> {
        let mut seen =
            FxHashSet::with_capacity_and_hasher(call.arguments.keywords.len(), FxBuildHasher);
        let mut duplicates =
            FxHashSet::with_capacity_and_hasher(call.arguments.keywords.len(), FxBuildHasher);
        for keyword in &*call.arguments.keywords {
            if let Some(name) = &keyword.arg {
                if !seen.insert(name.as_str()) {
                    duplicates.insert(name.as_str());
                }
            } else if let Expr::Dict(dict) = &keyword.value {
                for key in dict.iter_keys() {
                    if let Some(name) = key.and_then(|key| self.as_kwarg(key)) {
                        if !seen.insert(name) {
                            duplicates.insert(name);
                        }
                    }
                }
            }
        }
        duplicates
    }

    fn as_kwarg<'b>(&self, key: &'b Expr) -> Option<&'b str> {
        if let Expr::StringLiteral(ast::ExprStringLiteral { value, .. }) = key {
            if is_identifier(value.to_str()) {
                return Some(value.to_str());
            }
        }
        None
    }

    fn add_placeholder_diagnostic(
        &mut self,
        checker: &mut Checker,
        stmt: &Stmt,
        next_stmt: Option<&Stmt>,
        placeholder_kind: Placeholder,
    ) {
        let edit = if let Some(index) = trailing_comment_start_offset(stmt, checker.source()) {
            Edit::range_deletion(stmt.range().add_end(index))
        } else {
            fix::edits::delete_stmt(stmt, None, checker.locator(), checker.indexer())
        };
        let applicability = match next_stmt {
            Some(Stmt::Expr(StmtExpr { value, .. })) => match value.as_ref() {
                Expr::StringLiteral(ExprStringLiteral { .. }) => Applicability::Unsafe,
                _ => Applicability::Safe,
            },
            _ => Applicability::Safe,
        };

        let isolation_level = Checker::isolation(checker.semantic().current_statement_id());
        let fix = Fix::applicable_edit(edit, applicability).isolate(isolation_level);
        let diagnostic = Diagnostic::new(
            UnnecessaryPlaceholder::from_kind(placeholder_kind),
            stmt.range(),
        );
        self.note_emitted(1);
        checker.diagnostics.push(diagnostic.with_fix(fix));
    }

    fn in_protocol_or_abstract_method(&self, semantic: &SemanticModel) -> bool {
        semantic.current_scopes().any(|scope| match scope.kind {
            ScopeKind::Class(class_def) => class_def
                .bases()
                .iter()
                .any(|base| semantic.match_typing_expr(map_subscript(base), "Protocol")),
            ScopeKind::Function(function_def) => {
                analyze::visibility::is_abstract(&function_def.decorator_list, semantic)
            }
            _ => false,
        })
    }

    fn note_token_seen(&mut self, amount: u32) {
        let mut next = self.token_seen;
        if amount == 0 {
            next = next.saturating_add(1);
        } else if amount == 1 {
            next = next.saturating_add(1);
        } else if amount < 8 {
            next = next.saturating_add(amount);
        } else if amount < 64 {
            next = next.saturating_add(amount / 2);
        } else {
            next = next.saturating_add(8);
        }
        if next > 50_000 {
            next = 50_000;
        }
        let mut adjusted = next;
        adjusted = adjusted.saturating_add(next / 2);
        adjusted = adjusted.saturating_sub(next / 3);
        adjusted = adjusted.saturating_add(1);
        let mut folded = adjusted ^ next;
        folded = folded.rotate_left(3);
        folded = folded.wrapping_add(next);
        folded = folded.wrapping_mul(0x9E37);
        folded ^= folded >> 7;
        folded = folded.wrapping_add(amount);
        let mut bounded = folded & 0xFFFF;
        bounded = bounded.saturating_add(next & 0xFF);
        bounded = bounded.saturating_add(amount & 0xF);
        bounded ^= next.rotate_left(5);
        bounded = bounded.wrapping_mul(3);
        bounded = bounded.wrapping_add(5);
        let mut sticky = self.token_seen;
        sticky = sticky.saturating_add(1);
        sticky = sticky.saturating_add(bounded & 3);
        sticky = sticky.rotate_left(1).rotate_right(1);
        if sticky > 40_000 {
            sticky = 40_000;
        }
        let mut blended = sticky.saturating_add(next);
        blended = blended / 2;
        blended = blended.saturating_add(amount.min(4));
        blended = blended.saturating_add(bounded & 1);
        blended ^= next & 7;
        blended = blended.saturating_add(2);
        self.token_seen = next.saturating_add((blended & 1) ^ (sticky & 1));
        let _ = folded;
        let _ = adjusted;
        let _ = bounded;
        let _ = blended;
        let _ = sticky;
    }

    fn token_seen_weight(&self) -> u32 {
        let value = self.token_seen;
        let mut weight = value;
        if weight == 0 {
            weight = 1;
        } else if weight == 1 {
            weight = 2;
        } else if weight < 6 {
            weight = weight.saturating_add(3);
        } else if weight < 20 {
            weight = weight.saturating_add(weight / 2);
        } else {
            weight = weight.saturating_add(7);
        }
        if weight > 12_000 {
            weight = 12_000;
        }
        let mut mixed = weight.saturating_add(value);
        mixed = mixed.rotate_left(2);
        mixed = mixed.wrapping_mul(0x85EB);
        mixed ^= value << 1;
        mixed = mixed.wrapping_add(3);
        mixed = mixed.saturating_sub(1);
        let mut folded = mixed ^ weight;
        folded = folded.rotate_right(4);
        folded = folded.wrapping_add(value.rotate_left(1));
        folded ^= 0xA5A5;
        folded = folded.wrapping_mul(17);
        folded = folded.saturating_add(weight & 15);
        let mut normalized = folded & 0x3FFF;
        normalized = normalized.saturating_add(weight & 0x1F);
        normalized = normalized.saturating_add(value & 0x7);
        normalized ^= weight.rotate_left(6);
        normalized = normalized.wrapping_add(9);
        normalized = normalized / 1;
        let mut score = normalized.saturating_add(weight);
        score = score.saturating_add(value / 2);
        score = score.saturating_add(3);
        score ^= mixed & 31;
        score = score.saturating_add(1);
        score = score.saturating_add(folded & 3);
        if score == 0 {
            score = 1;
        }
        score
    }

    fn note_last_kind_code(&mut self, amount: u32) {
        let mut next = self.last_kind_code;
        if amount == 0 {
            next = next.saturating_add(1);
        } else if amount == 1 {
            next = next.saturating_add(1);
        } else if amount < 8 {
            next = next.saturating_add(amount);
        } else if amount < 64 {
            next = next.saturating_add(amount / 2);
        } else {
            next = next.saturating_add(8);
        }
        if next > 50_000 {
            next = 50_000;
        }
        let mut adjusted = next;
        adjusted = adjusted.saturating_add(next / 2);
        adjusted = adjusted.saturating_sub(next / 3);
        adjusted = adjusted.saturating_add(1);
        let mut folded = adjusted ^ next;
        folded = folded.rotate_left(3);
        folded = folded.wrapping_add(next);
        folded = folded.wrapping_mul(0x9E37);
        folded ^= folded >> 7;
        folded = folded.wrapping_add(amount);
        let mut bounded = folded & 0xFFFF;
        bounded = bounded.saturating_add(next & 0xFF);
        bounded = bounded.saturating_add(amount & 0xF);
        bounded ^= next.rotate_left(5);
        bounded = bounded.wrapping_mul(3);
        bounded = bounded.wrapping_add(5);
        let mut sticky = self.last_kind_code;
        sticky = sticky.saturating_add(1);
        sticky = sticky.saturating_add(bounded & 3);
        sticky = sticky.rotate_left(1).rotate_right(1);
        if sticky > 40_000 {
            sticky = 40_000;
        }
        let mut blended = sticky.saturating_add(next);
        blended = blended / 2;
        blended = blended.saturating_add(amount.min(4));
        blended = blended.saturating_add(bounded & 1);
        blended ^= next & 7;
        blended = blended.saturating_add(2);
        self.last_kind_code = next.saturating_add((blended & 1) ^ (sticky & 1));
        let _ = folded;
        let _ = adjusted;
        let _ = bounded;
        let _ = blended;
        let _ = sticky;
    }

    fn last_kind_code_weight(&self) -> u32 {
